import{m as e}from"./merge-BmcoofH2.js";const t={"unternehmensfuehrung-ueberblick":[{de:{term:"Normatives, strategisches, operatives Management",erklaerung:"Drei Ebenen der Unternehmensführung: normativ = Vision, Werte, Leitbild; strategisch = langfristige Planung und Strategien; operativ = konkrete Umsetzung im Alltag.",beispiel:"Loopy: Werte festlegen → Expansion planen → Schichtplan erstellen."},en:{term:"Normative, strategic, operational management",erklaerung:"Three levels of management: normative = vision, values, mission statement; strategic = long-term planning and strategies; operational = concrete day-to-day implementation.",beispiel:"Loopy: set values → plan expansion → draw up the shift plan."},hu:{term:"Normatív, stratégiai, operatív menedzsment",erklaerung:"A vállalatirányítás három szintje: normatív = jövőkép, értékek, küldetésnyilatkozat; stratégiai = hosszú távú tervezés és stratégiák; operatív = konkrét napi megvalósítás.",beispiel:"Loopy: értékek rögzítése → terjeszkedés tervezése → műszakbeosztás."}},{de:{term:"Hierarchiepyramide",erklaerung:"Topmanagement → Middle Management → Lower Management → Ausführungsebene. Je höher die Ebene, desto weniger Führungskräfte; Kleinbetriebe haben oft nur 1–2 Stufen."},en:{term:"Hierarchy pyramid",erklaerung:"Top management → middle management → lower management → operative level. The higher the level, the fewer managers; small businesses often have only 1–2 levels."},hu:{term:"Hierarchiapiramis",erklaerung:"Felső vezetés → középvezetés → alsó vezetés → végrehajtói szint. Minél magasabb a szint, annál kevesebb a vezető; a kisvállalkozásokban gyakran csak 1–2 szint van."}},{de:{term:"Topmanagement",erklaerung:"Oberste Führungsebene (Geschäftsführung, Vorstand) mit der Gesamtverantwortung für das Unternehmen; zuständig für normative und strategische Entscheidungen.",beispiel:"CEO einer Bank"},en:{term:"Top management",erklaerung:"Highest management level (managing directors, executive board) with overall responsibility for the company; responsible for normative and strategic decisions.",beispiel:"CEO of a bank"},hu:{term:"Felső vezetés",erklaerung:"A legfelső vezetési szint (ügyvezetés, igazgatóság), amely a vállalat egészéért felel; a normatív és stratégiai döntések gazdája.",beispiel:"Egy bank vezérigazgatója"}},{de:{term:"Middle Management",erklaerung:"Mittlere Führungsebene, z. B. Abteilungsleitung. Vermittelt zwischen Topmanagement und unteren Ebenen und gibt Vorgaben in die Abteilungen weiter.",beispiel:"Leiterin der Marketingabteilung"},en:{term:"Middle management",erklaerung:"Middle level of management, e.g. heads of department. Mediates between top management and the lower levels and passes targets on to the departments.",beispiel:"Head of the marketing department"},hu:{term:"Középvezetés",erklaerung:"A középső vezetési szint, pl. osztályvezetés. Közvetít a felső vezetés és az alsóbb szintek között, és továbbítja az elvárásokat az osztályoknak.",beispiel:"A marketingosztály vezetője"}},{de:{term:"Lower Management",erklaerung:"Untere Führungsebene (Team-, Gruppen-, Schichtleitung). Steuert die operative Umsetzung direkt mit den Mitarbeiter:innen der Ausführungsebene.",beispiel:"Schichtleiter in einer Produktionshalle"},en:{term:"Lower management",erklaerung:"Lowest level of management (team, group, shift leaders). Directs operational implementation directly with the employees on the operative level.",beispiel:"Shift supervisor in a production hall"},hu:{term:"Alsó vezetés",erklaerung:"A legalsó vezetési szint (csapat-, csoport-, műszakvezetés). Közvetlenül a végrehajtói szint munkatársaival irányítja az operatív megvalósítást.",beispiel:"Műszakvezető egy gyártócsarnokban"}},{de:{term:"Erfolgsfaktoren der Kommunikation",erklaerung:"Klarheit (eindeutig, verständlich), Offenheit (ehrlich, schafft Vertrauen), Regelmäßigkeit (rechtzeitig über feste Kanäle), Empathie (Bedürfnisse der Mitarbeiter:innen beachten)."},en:{term:"Success factors of communication",erklaerung:"Clarity (unambiguous, understandable), openness (honest, builds trust), regularity (on time via fixed channels), empathy (considering employees’ needs)."},hu:{term:"A kommunikáció sikertényezői",erklaerung:"Világosság (egyértelmű, érthető), nyitottság (őszinte, bizalmat épít), rendszeresség (időben, állandó csatornákon), empátia (a munkatársak igényeinek figyelembevétele)."}},{de:{term:"Intranet",erklaerung:"Interne, nur für Mitarbeiter:innen zugängliche Online-Plattform des Unternehmens für Informationen, Dokumente und Neuigkeiten.",beispiel:"Neue Urlaubsregelung wird im Intranet veröffentlicht."},en:{term:"Intranet",erklaerung:"A company’s internal online platform, accessible only to employees, for information, documents and news.",beispiel:"The new holiday policy is published on the intranet."},hu:{term:"Intranet",erklaerung:"A vállalat belső, csak a munkatársak számára elérhető online felülete információk, dokumentumok és hírek megosztására.",beispiel:"Az új szabadságolási szabályzatot az intraneten teszik közzé."}}],"normatives-management":[{de:{term:"Vision vs. Mission",erklaerung:"Vision = Zukunftsbild, „Leuchtturm“: Wohin will das Unternehmen? Mission = Auftrag und Nutzen: Warum existiert es? Jedes Unternehmen hat eine Mission, nicht jedes eine Vision.",beispiel:"Netflix-Mission: „To entertain the world.“"},en:{term:"Vision vs. mission",erklaerung:"Vision = picture of the future, “lighthouse”: where does the company want to go? Mission = purpose and benefit: why does it exist? Every company has a mission, not every one a vision.",beispiel:"Netflix mission: “To entertain the world.”"},hu:{term:"Jövőkép vs. küldetés",erklaerung:"Jövőkép (vízió) = a jövő képe, „világítótorony”: hová akar eljutni a vállalat? Küldetés (misszió) = feladat és haszon: miért létezik? Küldetése minden vállalatnak van, jövőképe nem mindnek.",beispiel:"A Netflix küldetése: „To entertain the world.”"}},{de:{term:"Unternehmensphilosophie",erklaerung:"Teil des Leitbilds: legt fest, welche Werte und Überzeugungen im Unternehmen wichtig sind und wie man mit Kund:innen, Mitarbeiter:innen und Umwelt umgeht.",beispiel:"Post AG: „Wir sind gelb, grün, bunt.“"},en:{term:"Corporate philosophy",erklaerung:"Part of the mission statement: defines which values and beliefs matter in the company and how it treats customers, employees and the environment.",beispiel:"Austrian Post: “We are yellow, green, colourful.”"},hu:{term:"Vállalati filozófia",erklaerung:"A küldetésnyilatkozat része: rögzíti, mely értékek és meggyőződések fontosak a vállalatnál, és hogyan bánik a vevőkkel, munkatársakkal és a környezettel.",beispiel:"Osztrák Posta: „Sárgák, zöldek, színesek vagyunk.”"}},{de:{term:"Operationalisierung von Zielen",erklaerung:"Ein Ziel wird überprüfbar, wenn es fünf Elemente enthält: Zielinhalt (Was?), Zielausmaß (Wie viel?), Zieltermin (Bis wann?), Zielverantwortung (Wer?), Zielort (Wo?).",beispiel:"Vertriebsleiter: Marktanteil in Indien bis Dezember um 7 % erhöhen."},en:{term:"Operationalising goals",erklaerung:"A goal becomes measurable when it contains five elements: content (what?), extent (how much?), deadline (by when?), responsibility (who?), location (where?).",beispiel:"Head of sales: increase market share in India by 7% by December."},hu:{term:"Célok operacionalizálása",erklaerung:"Egy cél akkor ellenőrizhető, ha öt elemet tartalmaz: tartalom (Mit?), mérték (Mennyit?), határidő (Meddig?), felelős (Ki?), hely (Hol?).",beispiel:"Értékesítési vezető: piaci részesedés növelése Indiában decemberig 7%-kal."}},{de:{term:"Zielbeziehungen",erklaerung:"Zielneutralität: Ziele beeinflussen sich nicht. Zielkomplementarität (Harmonie): eines fördert das andere. Zielkonflikt (Konkurrenz): eines behindert das andere.",beispiel:"Konflikt: Arbeitsplätze sichern ↔ Personalkosten senken"},en:{term:"Goal relationships",erklaerung:"Goal neutrality: goals do not affect each other. Complementarity (harmony): one promotes the other. Goal conflict (competition): one hinders the other.",beispiel:"Conflict: securing jobs ↔ cutting personnel costs"},hu:{term:"Célkapcsolatok",erklaerung:"Célsemlegesség: a célok nem hatnak egymásra. Célkomplementaritás (harmónia): az egyik elősegíti a másikat. Célkonfliktus (versengés): az egyik akadályozza a másikat.",beispiel:"Konfliktus: munkahelyek megőrzése ↔ személyi költségek csökkentése"}},{de:{term:"ESG-Kriterien",erklaerung:"Environmental (Umwelt), Social (Soziales), Governance (verantwortungsvolle Unternehmensführung). Laut Buch Pflicht-Bericht für große EU-Unternehmen ab 250 Mitarbeiter:innen."},en:{term:"ESG criteria",erklaerung:"Environmental, Social, Governance (responsible corporate management). According to the book, a mandatory report for large EU companies with 250 or more employees."},hu:{term:"ESG-kritériumok",erklaerung:"Environmental (környezet), Social (társadalom), Governance (felelős vállalatirányítás). A tankönyv szerint a legalább 250 fős nagy uniós vállalatoknak kötelező jelentést készíteniük."}}],"strategisches-operatives-management":[{de:{term:"Szenariotechnik",erklaerung:"Prognosemethode mit drei Zukunftsbildern: Best Case (positiv), Realistic Case (Trend setzt sich fort) und Worst Case (negativ).",beispiel:"Hotel plant Auslastung für gute, normale und schlechte Wintersaison."},en:{term:"Scenario technique",erklaerung:"Forecasting method with three pictures of the future: best case (positive), realistic case (trend continues) and worst case (negative).",beispiel:"A hotel plans occupancy for a good, normal and bad winter season."},hu:{term:"Forgatókönyv-technika",erklaerung:"Előrejelzési módszer három jövőképpel: legjobb eset (pozitív), reális eset (a trend folytatódik) és legrosszabb eset (negatív).",beispiel:"Egy szálloda jó, átlagos és rossz téli szezonra tervezi a kihasználtságot."}},{de:{term:"Delphi-Methode",erklaerung:"Prognosemethode: Expert:innen werden in mehreren Runden befragt; die Antworten werden zusammengefasst, zurückgemeldet und neu bewertet – so wird die Einschätzung immer genauer."},en:{term:"Delphi method",erklaerung:"Forecasting method: experts are surveyed in several rounds; the answers are summarised, fed back and reassessed – so the estimate becomes more and more precise."},hu:{term:"Delphi-módszer",erklaerung:"Előrejelzési módszer: a szakértőket több körben kérdezik meg; a válaszokat összesítik, visszajelzik és újraértékelik – így a becslés egyre pontosabb lesz."}},{de:{term:"BCG-Portfolio",erklaerung:"Matrix aus Marktwachstum und relativem Marktanteil: Question Marks (investieren oder aufgeben), Stars (fördern), Cashcows (abschöpfen), Poor Dogs (vom Markt nehmen)."},en:{term:"BCG portfolio",erklaerung:"Matrix of market growth and relative market share: question marks (invest or divest), stars (promote), cash cows (harvest), poor dogs (withdraw from the market)."},hu:{term:"BCG-portfólió",erklaerung:"Piacnövekedés és relatív piaci részesedés mátrixa: kérdőjelek (befektetés vagy kivonulás), sztárok (támogatás), fejőstehenek (lefölözés), döglött kutyák (kivonás a piacról)."}},{de:{term:"Ansoff-Matrix",erklaerung:"Vier Wachstumsstrategien aus Produkt (alt/neu) × Markt (alt/neu): Marktdurchdringung, Marktentwicklung, Produktentwicklung, Diversifikation.",beispiel:"Coca-Cola Zero = Produktentwicklung"},en:{term:"Ansoff matrix",erklaerung:"Four growth strategies from product (existing/new) × market (existing/new): market penetration, market development, product development, diversification.",beispiel:"Coca-Cola Zero = product development"},hu:{term:"Ansoff-mátrix",erklaerung:"Négy növekedési stratégia a termék (meglévő/új) × piac (meglévő/új) alapján: piacpenetráció, piacfejlesztés, termékfejlesztés, diverzifikáció.",beispiel:"Coca-Cola Zero = termékfejlesztés"}},{de:{term:"Relativer Marktanteil",erklaerung:"Eigener Marktanteil ÷ Marktanteil des größten Konkurrenten. Werte über 1,0 bedeuten Marktführerschaft.",beispiel:"12 % ÷ 4 % = 3,0 → Marktführer"},en:{term:"Relative market share",erklaerung:"Own market share ÷ market share of the largest competitor. Values above 1.0 mean market leadership.",beispiel:"12% ÷ 4% = 3.0 → market leader"},hu:{term:"Relatív piaci részesedés",erklaerung:"Saját piaci részesedés ÷ a legnagyobb versenytárs piaci részesedése. Az 1,0 feletti érték piacvezetést jelent.",beispiel:"12% ÷ 4% = 3,0 → piacvezető"}}],"organisieren-und-fuehren":[{de:{term:"Einliniensystem vs. Mehrliniensystem",erklaerung:"Einlinien: jede Stelle hat genau EINE Instanz (übersichtlich, aber lange Wege). Mehrlinien: ZWEI oder mehr Instanzen (kurze Wege, aber widersprüchliche Weisungen möglich)."},en:{term:"Line system vs. multiple-line system",erklaerung:"Line system: each position has exactly ONE superior (clear, but long channels). Multiple-line: TWO or more superiors (short channels, but contradictory instructions possible)."},hu:{term:"Egyvonalas vs. többvonalas rendszer",erklaerung:"Egyvonalas: minden munkakörnek pontosan EGY felettese van (áttekinthető, de hosszú utak). Többvonalas: KETTŐ vagy több felettes (rövid utak, de ellentmondó utasítások lehetségesek)."}},{de:{term:"Matrixorganisation",erklaerung:"Form des Mehrliniensystems: Gliederung gleichzeitig nach Funktionen (Einkauf, Marketing …) UND Divisionen (Produkte, Länder); Stellen haben zwei Vorgesetzte.",beispiel:"Produktmanagerin berichtet an Sparten- und Marketingleitung."},en:{term:"Matrix organisation",erklaerung:"Form of the multiple-line system: structured by functions (purchasing, marketing …) AND divisions (products, countries) at the same time; positions have two superiors.",beispiel:"A product manager reports to the division head and the head of marketing."},hu:{term:"Mátrixszervezet",erklaerung:"A többvonalas rendszer egyik formája: egyszerre tagolódik funkciók (beszerzés, marketing …) ÉS divíziók (termékek, országok) szerint; a munkaköröknek két felettesük van.",beispiel:"A termékmenedzser a divízióvezetőnek és a marketingvezetőnek is jelent."}},{de:{term:"Führungsstile nach Lewin",erklaerung:"Autoritär: Führungskraft entscheidet allein (schnell, aber demotivierend). Kooperativ: Mitarbeiter:innen entscheiden mit (motivierend, aber langsamer). Laissez-faire: viel Freiraum, Eingreifen nur bei Problemen."},en:{term:"Lewin’s leadership styles",erklaerung:"Authoritarian: the manager decides alone (fast, but demotivating). Cooperative: employees share decisions (motivating, but slower). Laissez-faire: much freedom, intervention only when problems arise."},hu:{term:"Lewin vezetési stílusai",erklaerung:"Autoriter: a vezető egyedül dönt (gyors, de demotiváló). Kooperatív: a munkatársak részt vesznek a döntésben (motiváló, de lassabb). Laissez-faire: nagy szabadság, beavatkozás csak probléma esetén."}},{de:{term:"Management by Objectives (MbO)",erklaerung:"Führungskonzept, bei dem Führungskraft und Mitarbeiter:in Ziele GEMEINSAM vereinbaren; der Weg zum Ziel bleibt weitgehend frei. Abgrenzung: Management by Results gibt Ergebnisse vor.",beispiel:"Jahresgespräch: gemeinsam 5 % mehr Neukund:innen vereinbart"},en:{term:"Management by objectives (MbO)",erklaerung:"Management concept in which manager and employee agree goals TOGETHER; the way to reach them is largely left open. Contrast: management by results sets results from above.",beispiel:"Annual review: 5% more new customers agreed together"},hu:{term:"Célok szerinti vezetés (MbO)",erklaerung:"Vezetési koncepció, amelyben a vezető és a munkatárs KÖZÖSEN állapodik meg a célokban; a cél elérésének módja nagyrészt szabad. Szemben: a management by results előírja az eredményeket.",beispiel:"Éves értékelő beszélgetés: közösen 5% több új ügyfél"}},{de:{term:"Zentralisation vs. Dezentralisation",erklaerung:"Zentralisation: wenige Personen treffen alle wesentlichen Entscheidungen. Dezentralisation: Entscheidungen werden an viele Personen delegiert; die Führung sichert den Informationsaustausch."},en:{term:"Centralisation vs. decentralisation",erklaerung:"Centralisation: a few people make all the important decisions. Decentralisation: decisions are delegated to many people; management ensures the exchange of information."},hu:{term:"Centralizáció vs. decentralizáció",erklaerung:"Centralizáció: kevés személy hozza meg az összes lényeges döntést. Decentralizáció: a döntéseket sok személyre delegálják; a vezetés az információcserét biztosítja."}}],personalbedarfsplanung:[{de:{term:"Quantitativer vs. qualitativer Personalbedarf",erklaerung:"Quantitativ = WIE VIELE Mitarbeiter:innen (schwankt durch Saison, Ausfälle, Nachfrage). Qualitativ = WELCHE Qualifikationen (steht in der Stellenbeschreibung). Dazu: örtlich (wo?) und zeitlich (wann?)."},en:{term:"Quantitative vs. qualitative personnel requirement",erklaerung:"Quantitative = HOW MANY employees (varies with season, absences, demand). Qualitative = WHICH qualifications (set out in the job description). Also: local (where?) and temporal (when?)."},hu:{term:"Mennyiségi vs. minőségi létszámszükséglet",erklaerung:"Mennyiségi = HÁNY munkatárs kell (változik a szezon, a kiesések, a kereslet szerint). Minőségi = MILYEN képzettség (a munkaköri leírásban áll). Ezen kívül: területi (hol?) és időbeli (mikor?)."}},{de:{term:"Anforderungsprofil",erklaerung:"Erster Schritt im Recruiting: legt fest, was Bewerber:innen mitbringen müssen – allgemeine Anforderungen, Ausbildung, Persönlichkeit, Branchenkenntnisse.",beispiel:"Bankberater:in: HAK-Matura, Kommunikationsstärke, Englisch"},en:{term:"Job requirements profile",erklaerung:"First step in recruiting: defines what applicants must bring – general requirements, education, personality, industry knowledge.",beispiel:"Bank adviser: business school diploma, strong communication skills, English"},hu:{term:"Követelményprofil",erklaerung:"A toborzás első lépése: rögzíti, mivel kell rendelkezniük a jelentkezőknek – általános követelmények, végzettség, személyiség, ágazati ismeretek.",beispiel:"Banki tanácsadó: kereskedelmi akadémiai érettségi, jó kommunikáció, angol"}},{de:{term:"Assessment-Center",erklaerung:"Aufwendiges Auswahlverfahren: mehrere Bewerber:innen lösen bis zu 3 Tage lang Gruppenaufgaben, Rollenspiele und Präsentationen – v. a. für Führungspositionen."},en:{term:"Assessment centre",erklaerung:"Elaborate selection procedure: several applicants solve group tasks, role plays and presentations for up to 3 days – mainly for management positions."},hu:{term:"Assessment center (értékelő központ)",erklaerung:"Költséges kiválasztási eljárás: több jelentkező akár 3 napon át csoportos feladatokat, szerepjátékokat és prezentációkat old meg – főleg vezetői pozíciókhoz."}},{de:{term:"Postensuchtage",erklaerung:"Kündigt der Arbeitgeber, hat der Arbeitnehmer während der Kündigungsfrist Anspruch auf bezahlte Freizeit zur Jobsuche: 1/5 der wöchentlichen Arbeitszeit.",beispiel:"40-Stunden-Woche → 8 Stunden pro Woche frei"},en:{term:"Job-search time off",erklaerung:"If the employer gives notice, the employee is entitled to paid time off to look for a job during the notice period: 1/5 of the weekly working time.",beispiel:"40-hour week → 8 hours off per week"},hu:{term:"Álláskeresési idő",erklaerung:"Munkáltatói felmondás esetén a munkavállalónak a felmondási idő alatt fizetett szabadidő jár álláskeresésre: a heti munkaidő 1/5-e.",beispiel:"Heti 40 óra → hetente 8 óra szabad"}},{de:{term:"Abfertigung neu (MVK)",erklaerung:"Arbeitgeber zahlt monatlich 1,53 % des Bruttoentgelts in eine Mitarbeitervorsorgekasse. Auszahlung laut Buch nach mind. 3 Einzahlungsjahren, sonst wandert der „Rucksack“ mit.",beispiel:"3.000 € brutto → 45,90 € pro Monat an die MVK"},en:{term:"New severance pay (MVK)",erklaerung:"The employer pays 1.53% of gross pay monthly into an employee provision fund. According to the book, payout after at least 3 years of contributions, otherwise the “backpack” moves on with the employee.",beispiel:"€3,000 gross → €45.90 per month to the fund"},hu:{term:"Új végkielégítési rendszer (MVK)",erklaerung:"A munkáltató havonta a bruttó bér 1,53%-át fizeti be egy munkavállalói végkielégítési pénztárba. Kifizetés a tankönyv szerint legalább 3 befizetési év után, különben a „hátizsák” továbbvándorol.",beispiel:"Bruttó 3000 € → havi 45,90 € a pénztárba"}}],personaleinsatzgestaltung:[{de:{term:"Stufenbau im Arbeitsrecht",erklaerung:"Europarecht → nationale Gesetze → Kollektivvertrag → Betriebsvereinbarung → Einzelarbeitsvertrag. Untere Stufen dürfen nur zugunsten der Arbeitnehmer:innen abweichen.",beispiel:"Vertrag darf mehr Gehalt als der KV vorsehen, nie weniger."},en:{term:"Hierarchy of norms in labour law",erklaerung:"EU law → national laws → collective agreement → works agreement → individual employment contract. Lower levels may only deviate in favour of employees.",beispiel:"A contract may provide more pay than the collective agreement, never less."},hu:{term:"Munkajogi jogforrási hierarchia",erklaerung:"Uniós jog → nemzeti törvények → kollektív szerződés → üzemi megállapodás → egyéni munkaszerződés. Az alsóbb szintek csak a munkavállalók javára térhetnek el.",beispiel:"A szerződés több fizetést írhat elő, mint a kollektív szerződés, kevesebbet soha."}},{de:{term:"Fürsorgepflicht vs. Treuepflicht",erklaerung:"Fürsorgepflicht (Arbeitgeber): Schutz vor Gefahren, Gesundheit, Gleichbehandlung, Sonderschutz. Treuepflicht (Arbeitnehmer): Verschwiegenheit, keine Geschenke annehmen, nicht rufschädigen, Konkurrenzverbot."},en:{term:"Duty of care vs. duty of loyalty",erklaerung:"Duty of care (employer): protection from hazards, health, equal treatment, special protection. Duty of loyalty (employee): confidentiality, accepting no gifts, no damage to reputation, non-compete."},hu:{term:"Gondoskodási vs. hűségkötelezettség",erklaerung:"Gondoskodási kötelezettség (munkáltató): veszélyek elleni védelem, egészség, egyenlő bánásmód, különleges védelem. Hűségkötelezettség (munkavállaló): titoktartás, ajándék elutasítása, jó hírnév védelme, versenytilalom."}},{de:{term:"Bedürfnispyramide (Maslow)",erklaerung:"Fünf Stufen von unten nach oben: Grundbedürfnisse, Sicherheit, soziale Bedürfnisse, Anerkennung, Selbstverwirklichung. Höhere Bedürfnisse werden erst wichtig, wenn untere erfüllt sind.",beispiel:"Anerkennung: Prämie für die beste Verkäuferin"},en:{term:"Hierarchy of needs (Maslow)",erklaerung:"Five levels from bottom to top: basic needs, safety, social needs, esteem, self-actualisation. Higher needs only become important once lower ones are met.",beispiel:"Esteem: a bonus for the best sales assistant"},hu:{term:"Szükségletpiramis (Maslow)",erklaerung:"Öt szint alulról felfelé: alapszükségletek, biztonság, társas szükségletek, elismerés, önmegvalósítás. A magasabb szükségletek csak az alacsonyabbak kielégítése után válnak fontossá.",beispiel:"Elismerés: prémium a legjobb eladónak"}},{de:{term:"Jobenlargement vs. Jobenrichment",erklaerung:"Jobenlargement = zusätzliche Aufgaben mit GLEICHEN Anforderungen (quantitative Erweiterung). Jobenrichment = Aufgaben mit HÖHEREN Anforderungen und mehr Verantwortung (qualitative Erweiterung)."},en:{term:"Job enlargement vs. job enrichment",erklaerung:"Job enlargement = additional tasks with the SAME requirements (quantitative extension). Job enrichment = tasks with HIGHER requirements and more responsibility (qualitative extension)."},hu:{term:"Munkakörbővítés vs. munkagazdagítás",erklaerung:"Munkakörbővítés (job enlargement) = további, AZONOS követelményű feladatok (mennyiségi bővítés). Munkagazdagítás (job enrichment) = MAGASABB követelményű feladatok, több felelősséggel (minőségi bővítés)."}},{de:{term:"Betriebsrat",erklaerung:"Vertritt die Belegschaft gegenüber der Unternehmensleitung; möglich ab 5 Arbeitnehmer:innen (über 18). Wählen ab 16, gewählt werden ab 18 und 6 Monaten im Betrieb."},en:{term:"Works council",erklaerung:"Represents the workforce towards management; possible from 5 employees (over 18). Voting from 16, standing for election from 18 and after 6 months in the company."},hu:{term:"Üzemi tanács",erklaerung:"A munkavállalókat képviseli a vállalatvezetéssel szemben; 5 (18 év feletti) munkavállalótól hozható létre. Választani 16, megválasztva lenni 18 évesen és 6 hónap üzemi munka után lehet."}}],personalbeurteilung:[{de:{term:"Zeitlohn vs. Leistungslohn",erklaerung:"Zeitlohn: Entgelt pro Zeiteinheit (Stunde, Monat), unabhängig von der Menge. Leistungslohn: Akkordlohn (Stück- oder Zeitakkord) oder Prämienlohn (Zeitlohn + Prämie).",beispiel:"Erntehelfer:in pro kg = Stückakkord"},en:{term:"Time-based vs. performance-based pay",erklaerung:"Time-based pay: pay per unit of time (hour, month), regardless of quantity. Performance-based pay: piece-rate pay (per piece or per standard time) or bonus pay (time pay + bonus).",beispiel:"Harvest worker paid per kg = piece rate"},hu:{term:"Időbér vs. teljesítménybér",erklaerung:"Időbér: díjazás időegységenként (óra, hónap), a mennyiségtől függetlenül. Teljesítménybér: akkordbér (darab- vagy időakkord) vagy prémiumos bér (időbér + prémium).",beispiel:"Kilogrammonként fizetett idénymunkás = darabakkord"}},{de:{term:"Halo-Effekt",erklaerung:"Beurteilungsfehler: Eine auffällige Eigenschaft „überstrahlt“ alle anderen und färbt das Gesamturteil positiv oder negativ.",beispiel:"Weil ein Mitarbeiter sehr redegewandt ist, wird auch seine Genauigkeit überschätzt."},en:{term:"Halo effect",erklaerung:"Appraisal error: one striking characteristic “outshines” all the others and colours the overall judgement positively or negatively.",beispiel:"Because an employee is very eloquent, his accuracy is overestimated too."},hu:{term:"Haloeffektus (glóriahatás)",erklaerung:"Értékelési hiba: egy feltűnő tulajdonság „beragyogja” az összes többit, és pozitívan vagy negatívan színezi az összképet.",beispiel:"Mivel egy munkatárs nagyon jól beszél, a pontosságát is túlértékelik."}},{de:{term:"Cafeteria-System",erklaerung:"Mitarbeiter:innen wählen aus einem Angebot an Anreizen selbst, was ihnen am meisten nützt – z. B. Zusatzversicherung, zusätzlicher Urlaub oder Firmen-Pkw.",beispiel:"Budget von 1.000 € pro Jahr frei für Öffi-Ticket oder Fitness"},en:{term:"Cafeteria system",erklaerung:"Employees choose for themselves from a range of incentives what benefits them most – e.g. supplementary insurance, extra holiday or a company car.",beispiel:"€1,000 a year to spend freely on a public transport pass or fitness"},hu:{term:"Kafetéria-rendszer",erklaerung:"A munkatársak maguk választják ki a juttatások kínálatából azt, ami számukra a leghasznosabb – pl. kiegészítő biztosítás, plusz szabadság vagy céges autó.",beispiel:"Évi 1000 € keret szabadon bérletre vagy edzőteremre"}},{de:{term:"Personalintensität",erklaerung:"Kennzahl des Personalcontrollings: Personalkosten · 100 ÷ Betriebsleistung. Zeigt, wie viel Prozent der Betriebsleistung auf Personalkosten entfallen.",beispiel:"416.000 · 100 ÷ 1.300.000 = 32 %"},en:{term:"Personnel intensity",erklaerung:"HR controlling key figure: personnel costs · 100 ÷ operating output. Shows what percentage of operating output is accounted for by personnel costs.",beispiel:"416,000 · 100 ÷ 1,300,000 = 32%"},hu:{term:"Személyi intenzitás",erklaerung:"A személyügyi kontrolling mutatója: személyi költségek · 100 ÷ üzemi teljesítmény. Megmutatja, hogy az üzemi teljesítmény hány százalékát teszik ki a személyi költségek.",beispiel:"416 000 · 100 ÷ 1 300 000 = 32%"}},{de:{term:"Mitarbeiterbeteiligung",erklaerung:"Erfolgsbeteiligung = Bonus für besondere Leistungen. Kapitalbeteiligung = Belegschaftsaktien, Mitarbeiterstiftung. Gewinnbeteiligung = Anteil am ausgeschütteten Gewinn."},en:{term:"Employee participation",erklaerung:"Performance-related participation = bonus for special achievements. Capital participation = employee shares, employee foundation. Profit sharing = share of the distributed profit."},hu:{term:"Munkavállalói részesedés",erklaerung:"Eredményrészesedés = bónusz különleges teljesítményért. Tőkerészesedés = dolgozói részvények, munkavállalói alapítvány. Nyereségrészesedés = részesedés a kifizetett nyereségből."}}]},n={produktionsbetriebe:[{de:{term:"Konsumgüter- vs. Investitionsgüterbetrieb",erklaerung:"Einteilung nach den Abnehmern: Konsumgüterbetriebe erzeugen Sachgüter für Endverbraucher:innen, Investitionsgüterbetriebe für andere Unternehmen.",beispiel:"Möbel, Getränke ↔ Fließband, Roboter, Stahlbleche"},en:{term:"Consumer goods vs. capital goods producer",erklaerung:"Classification by customer: consumer goods producers make physical goods for end consumers, capital goods producers make them for other businesses.",beispiel:"Furniture, drinks ↔ conveyor belts, robots, steel sheets"},hu:{term:"Fogyasztási cikkeket vs. beruházási javakat gyártó üzem",erklaerung:"Felosztás a vevők szerint: a fogyasztási cikkeket gyártó üzemek a végső fogyasztóknak, a beruházási javakat gyártó üzemek más vállalatoknak állítanak elő tárgyi javakat.",beispiel:"Bútor, italok ↔ futószalag, robot, acéllemez"}},{de:{term:"Gewerbe- vs. Industriebetrieb",erklaerung:"Gewerbe: arbeitsintensiv, Inhaber:in führt, KMU, wenig Automatisierung. Industrie: anlagenintensiv (hohe Fixkosten), Management führt, Mittel-/Großbetrieb, stark automatisiert.",beispiel:"Naturbackstube Honeder ↔ Industriebäckerei backaldrin"},en:{term:"Craft business vs. industrial company",erklaerung:"Craft: labour-intensive, run by the owner, SME, little automation. Industry: capital-intensive (high fixed costs), run by managers, medium/large, highly automated.",beispiel:"Small artisan bakery ↔ industrial bakery"},hu:{term:"Kisipari vs. ipari vállalat",erklaerung:"Kisipar: munkaigényes, a tulajdonos vezeti, kkv, kevés automatizálás. Ipar: eszközigényes (magas fix költség), menedzsment vezeti, közép-/nagyvállalat, erősen automatizált.",beispiel:"Kézműves pékség ↔ ipari nagypékség"}},{de:{term:"Standortfaktoren (3 Gruppen)",erklaerung:"Beschaffungsseitig (Fläche, Arbeitskräfte, Rohstoffe, Mieten), produktionsbezogen (Vorschriften, Steuern, Personalkosten, Förderungen), absatzorientiert (Kundennähe, Wettbewerb, Image).",beispiel:"Papierfabrik an einem Fluss: Rohstofftransport und Wasser"},en:{term:"Location factors (3 groups)",erklaerung:"Procurement-related (land, workers, raw materials, rents), production-related (regulations, taxes, labour costs, subsidies), sales-oriented (customer proximity, competition, image).",beispiel:"Paper mill on a river: raw material transport and water"},hu:{term:"Telephelyi tényezők (3 csoport)",erklaerung:"Beszerzési oldali (terület, munkaerő, nyersanyag, bérleti díj), termeléshez kapcsolódó (előírások, adók, bérköltség, támogatások), értékesítési oldali (vevők közelsége, verseny, imázs).",beispiel:"Papírgyár folyó mellett: nyersanyagszállítás és víz"}},{de:{term:"Nachhaltigkeit: People – Planet – Profit",erklaerung:"Drei Dimensionen nachhaltiger Produktion: sozial (faire Arbeit, Gesundheit, Weiterbildung), ökologisch (erneuerbare Energie, Effizienz), ökonomisch (Gesetze, keine Korruption, fairer Wettbewerb).",beispiel:"Photovoltaik auf dem Hallendach = Planet"},en:{term:"Sustainability: people – planet – profit",erklaerung:"Three dimensions of sustainable production: social (fair work, health, training), ecological (renewable energy, efficiency), economic (laws, no corruption, fair competition).",beispiel:"Solar panels on the factory roof = planet"},hu:{term:"Fenntarthatóság: People – Planet – Profit",erklaerung:"A fenntartható termelés három dimenziója: társadalmi (tisztességes munka, egészség, továbbképzés), ökológiai (megújuló energia, hatékonyság), gazdasági (törvények, korrupciómentesség, tisztességes verseny).",beispiel:"Napelem a csarnok tetején = Planet"}}],"leistungserstellungsprozess-produktion":[{de:{term:"Auftrags- vs. Vorratsproduktion",erklaerung:"Make to order: Produktion erst bei konkretem Kundenauftrag, Kundenwünsche möglich. Make to stock: Produktion nach prognostizierter Absatzmenge, immer lieferfähig.",beispiel:"Spritzgießmaschine ↔ Waschmittel, Getränke"},en:{term:"Make to order vs. make to stock",erklaerung:"Make to order: production only after a specific customer order, customer wishes possible. Make to stock: production based on forecast sales, always able to deliver.",beispiel:"Injection moulding machine ↔ detergent, drinks"},hu:{term:"Megrendelésre vs. készletre gyártás",erklaerung:"Make to order: gyártás csak konkrét vevői megrendelés után, egyedi igények lehetségesek. Make to stock: gyártás az előrejelzett értékesítés alapján, mindig szállítóképes.",beispiel:"Fröccsöntő gép ↔ mosószer, italok"}},{de:{term:"Nettobedarf",erklaerung:"Bedarf laut Stückliste · Produktionsmenge = Bruttobedarf; Bruttobedarf − Lagerbestand = Nettobedarf (tatsächlich selbst zu fertigen oder zuzukaufen).",beispiel:"120 Tische · 4 Beine = 480 − 75 auf Lager = 405 Tischbeine"},en:{term:"Net requirement",erklaerung:"Requirement per bill of materials · production quantity = gross requirement; gross requirement − stock = net requirement (actually to be produced or bought).",beispiel:"120 tables · 4 legs = 480 − 75 in stock = 405 table legs"},hu:{term:"Nettó szükséglet",erklaerung:"Darabjegyzék szerinti szükséglet · gyártási mennyiség = bruttó szükséglet; bruttó szükséglet − raktárkészlet = nettó szükséglet (ténylegesen legyártandó vagy beszerzendő).",beispiel:"120 asztal · 4 láb = 480 − 75 raktáron = 405 asztalláb"}},{de:{term:"Durchlaufzeit",erklaerung:"Durchführungszeit (Rüstzeit + Bearbeitungszeit) + Übergangszeit (Liegezeit + Transportzeit).",beispiel:"2 h rüsten + 6 h bearbeiten + 3 h liegen + 1 h Transport = 12 h"},en:{term:"Lead time (throughput time)",erklaerung:"Execution time (set-up time + processing time) + transition time (waiting time + transport time).",beispiel:"2 h set-up + 6 h processing + 3 h waiting + 1 h transport = 12 h"},hu:{term:"Átfutási idő",erklaerung:"Végrehajtási idő (átállási idő + megmunkálási idő) + átmeneti idő (várakozási idő + szállítási idő).",beispiel:"2 ó átállás + 6 ó megmunkálás + 3 ó várakozás + 1 ó szállítás = 12 ó"}},{de:{term:"Vorwärts- vs. Rückwärtsterminierung",erklaerung:"Vorwärts: sofort starten → frühester Endtermin, wenig Zeitdruck, aber Kapitalbindung durch Lager. Rückwärts: vom Liefertermin zurückrechnen → spätester Start, geringe Lagerkosten, kein Puffer."},en:{term:"Forward vs. backward scheduling",erklaerung:"Forward: start at once → earliest end date, little time pressure, but capital tied up in stock. Backward: work back from the delivery date → latest start, low storage costs, no buffer."},hu:{term:"Előre vs. visszafelé ütemezés",erklaerung:"Előre: azonnali kezdés → legkorábbi befejezés, kevés időnyomás, de a készlet tőkét köt le. Visszafelé: a határidőtől visszaszámolva → legkésőbbi kezdés, alacsony raktárköltség, nincs tartalék."}},{de:{term:"Fertigungsart vs. Organisationstyp",erklaerung:"Fertigungsart = WIE VIELE gleiche Produkte (Einzel-, Serien-, Massenfertigung). Organisationstyp = WIE die Stationen angeordnet sind (Werkstatt-, Fließband-, Gruppen-, Baustellenfertigung).",beispiel:"Tunnelbau: Einzelfertigung + Baustellenfertigung"},en:{term:"Type of manufacturing vs. type of organisation",erklaerung:"Type of manufacturing = HOW MANY identical products (one-off, batch, mass). Type of organisation = HOW workstations are arranged (workshop, assembly line, group, site production).",beispiel:"Tunnel building: one-off production + site production"},hu:{term:"Gyártási mód vs. szervezési forma",erklaerung:"Gyártási mód = HÁNY azonos termék (egyedi, sorozat-, tömeggyártás). Szervezési forma = HOGYAN helyezkednek el a munkahelyek (műhelyrendszerű, futószalagos, csoportos, helyszíni gyártás).",beispiel:"Alagútépítés: egyedi gyártás + helyszíni gyártás"}}],"investition-finanzierung-ueberblick":[{de:{term:"Investition vs. Finanzierung (Bilanz)",erklaerung:"Investition = Mittelverwendung, WOFÜR das Geld eingesetzt wird (Aktiva). Finanzierung = Mittelherkunft, WOHER das Geld kommt (Passiva). Die Finanzierung ermöglicht die Investition.",beispiel:"Bankkredit (Finanzierung) → neue Maschine (Investition)"},en:{term:"Investment vs. financing (balance sheet)",erklaerung:"Investment = use of funds, WHAT the money is used for (assets). Financing = source of funds, WHERE the money comes from (liabilities and equity). Financing makes investment possible.",beispiel:"Bank loan (financing) → new machine (investment)"},hu:{term:"Beruházás vs. finanszírozás (mérleg)",erklaerung:"Beruházás = eszközfelhasználás, MIRE fordítják a pénzt (eszközök). Finanszírozás = forráseredet, HONNAN jön a pénz (források). A finanszírozás teszi lehetővé a beruházást.",beispiel:"Bankhitel (finanszírozás) → új gép (beruházás)"}},{de:{term:"Aktiva",erklaerung:"Linke Bilanzseite = Vermögen: Anlagevermögen und Umlaufvermögen. Zeigt die Mittelverwendung."},en:{term:"Assets",erklaerung:"Left side of the balance sheet = what the company owns: fixed assets and current assets. Shows the use of funds."},hu:{term:"Eszközök (aktívák)",erklaerung:"A mérleg bal oldala = vagyon: befektetett eszközök és forgóeszközök. Az eszközfelhasználást mutatja."}},{de:{term:"Passiva",erklaerung:"Rechte Bilanzseite = Kapital: Eigenkapital und Fremdkapital. Zeigt die Mittelherkunft."},en:{term:"Liabilities and equity",erklaerung:"Right side of the balance sheet = capital: equity and debt. Shows the source of funds."},hu:{term:"Források (passzívák)",erklaerung:"A mérleg jobb oldala = tőke: saját tőke és idegen tőke. A források eredetét mutatja."}},{de:{term:"Anlagevermögen",erklaerung:"Vermögen, das dem Betrieb langfristig dient: immaterielle Güter (Patente), Sachanlagen (Maschinen, Gebäude) und Finanzanlagen (langfristige Beteiligungen).",beispiel:"Loopys Schokoladenanlage"},en:{term:"Fixed assets",erklaerung:"Assets that serve the business in the long term: intangible assets (patents), tangible assets (machines, buildings) and financial assets (long-term stakes).",beispiel:"Loopy's chocolate production line"},hu:{term:"Befektetett eszközök",erklaerung:"Tartósan a vállalkozást szolgáló vagyon: immateriális javak (szabadalmak), tárgyi eszközök (gépek, épületek) és befektetett pénzügyi eszközök (tartós részesedések).",beispiel:"Loopy csokoládégyártó berendezése"}},{de:{term:"Umlaufvermögen",erklaerung:"Kurzfristig gebundenes Vermögen, das sich laufend verändert: Vorräte, Forderungen, Kassa und Bankguthaben.",beispiel:"Zuckervorrat, offene Kundenrechnungen, Geld in der Kassa"},en:{term:"Current assets",erklaerung:"Assets held short-term that change constantly: inventory, receivables, cash and bank balances.",beispiel:"Sugar in stock, unpaid customer invoices, cash in the till"},hu:{term:"Forgóeszközök",erklaerung:"Rövid távon lekötött, folyamatosan változó vagyon: készletek, követelések, pénztár és bankbetét.",beispiel:"Cukorkészlet, kifizetetlen vevőszámlák, pénz a kasszában"}},{de:{term:"Eigenkapital vs. Fremdkapital",erklaerung:"Eigenkapital: Mittel der Eigentümer:innen (Einlagen, Gewinn, Rücklagen), unbefristet. Fremdkapital: Mittel von Gläubigern (Kredite, Verbindlichkeiten, Rückstellungen), befristet und verzinst."},en:{term:"Equity vs. debt",erklaerung:"Equity: funds from the owners (contributions, profit, reserves), no fixed term. Debt: funds from creditors (loans, payables, provisions), fixed term and interest-bearing."},hu:{term:"Saját tőke vs. idegen tőke",erklaerung:"Saját tőke: a tulajdonosok forrásai (betétek, nyereség, tartalékok), határozatlan időre. Idegen tőke: hitelezők forrásai (hitelek, kötelezettségek, céltartalékok), határozott időre és kamatozó."}},{de:{term:"Ebenen der Finanzplanung",erklaerung:"Normativ: langfristige finanzielle Ziele. Strategisch: Budgetplanung, Investitionsprojekte bewerten. Operativ: laufende Kostenkontrolle, Liquidität für Gehälter und Rechnungen sichern.",beispiel:"Gehälter im nächsten Monat sicherstellen = operativ"},en:{term:"Levels of financial planning",erklaerung:"Normative: long-term financial goals. Strategic: budget planning, evaluating investment projects. Operational: ongoing cost control, securing liquidity for salaries and bills.",beispiel:"Making sure next month's salaries can be paid = operational"},hu:{term:"A pénzügyi tervezés szintjei",erklaerung:"Normatív: hosszú távú pénzügyi célok. Stratégiai: költségvetés-tervezés, beruházási projektek értékelése. Operatív: folyamatos költségellenőrzés, likviditás a bérekhez és számlákhoz.",beispiel:"A jövő havi bérek biztosítása = operatív"}}],investitionsmanagement:[{de:{term:"Kalkulatorische Zinsen",erklaerung:"(Anschaffungskosten + Restwert) / 2 · Zinssatz. Verzinsung des durchschnittlich gebundenen Kapitals; Teil der Kapitalkosten in der Kostenvergleichsrechnung.",beispiel:"(50.000 + 10.000) / 2 · 5 % = 1.500 € pro Jahr"},en:{term:"Imputed interest",erklaerung:"(Acquisition cost + residual value) / 2 · interest rate. Interest on the average capital tied up; part of capital costs in the cost comparison method.",beispiel:"(50,000 + 10,000) / 2 · 5% = €1,500 per year"},hu:{term:"Kalkulatív kamat",erklaerung:"(Bekerülési érték + maradványérték) / 2 · kamatláb. Az átlagosan lekötött tőke kamata; a költség-összehasonlító számításban a tőkeköltség része.",beispiel:"(50 000 + 10 000) / 2 · 5% = évi 1500 €"}},{de:{term:"Kritische Menge",erklaerung:"Differenz der Fixkosten / Differenz der variablen Kosten pro Einheit. Darüber lohnt sich die Alternative mit den niedrigeren variablen Kosten, darunter die mit den niedrigeren Fixkosten.",beispiel:"(292.500 − 221.000) / (150 − 110) = 1.787,5 h"},en:{term:"Critical volume",erklaerung:"Difference in fixed costs / difference in variable costs per unit. Above it, the option with lower variable costs pays off; below it, the one with lower fixed costs.",beispiel:"(292,500 − 221,000) / (150 − 110) = 1,787.5 h"},hu:{term:"Kritikus mennyiség",erklaerung:"Fix költségek különbsége / egységnyi változó költségek különbsége. Felette az alacsonyabb változó költségű, alatta az alacsonyabb fix költségű alternatíva éri meg.",beispiel:"(292 500 − 221 000) / (150 − 110) = 1787,5 óra"}},{de:{term:"Rentabilität (Investitionsrechnung)",erklaerung:"(Gewinn + kalk. Zinsen) · 100 / Ø Kapitaleinsatz; Ø Kapitaleinsatz = (Anschaffungskosten + Restwert) / 2. Ohne Gewinn: Kosteneinsparung · 100 / Ø Kapitaleinsatz.",beispiel:"(75.000 + 5.000) · 100 / 125.000 = 64 %"},en:{term:"Return on investment (investment appraisal)",erklaerung:"(Profit + imputed interest) · 100 / average capital employed; average capital = (acquisition cost + residual value) / 2. Without profit: cost savings · 100 / average capital.",beispiel:"(75,000 + 5,000) · 100 / 125,000 = 64%"},hu:{term:"Jövedelmezőség (beruházás-gazdaságossági számítás)",erklaerung:"(Nyereség + kalkulatív kamat) · 100 / átlagos tőkeráfordítás; átlagos tőke = (bekerülési érték + maradványérték) / 2. Nyereség nélkül: költségmegtakarítás · 100 / átlagos tőke.",beispiel:"(75 000 + 5000) · 100 / 125 000 = 64%"}},{de:{term:"Durchschnitts- vs. Kumulationsmethode",erklaerung:"Zwei Arten der Amortisationsrechnung: Durchschnittsmethode bei jährlich gleich hohen Rückflüssen; Kumulationsmethode bei unterschiedlichen Rückflüssen – sie werden addiert, bis sie das Kapital decken."},en:{term:"Average vs. cumulative method",erklaerung:"Two types of payback calculation: average method when annual returns are equal; cumulative method when returns differ – they are added up until they cover the capital invested."},hu:{term:"Átlagmódszer vs. kumulációs módszer",erklaerung:"A megtérülési számítás két fajtája: átlagmódszer egyenlő éves visszaáramlásnál; kumulációs módszer eltérő visszaáramlásnál – ezeket addig adják össze, amíg fedezik a befektetett tőkét."}},{de:{term:"Scoring-Methode (Nutzwertanalyse)",erklaerung:"Bewertet Alternativen auch nach qualitativen Kriterien: Kriterien festlegen und gewichten (100 %), Punkte vergeben, Punkte × Gewichtung addieren – höchster Nutzwert gewinnt.",beispiel:"E-Lieferwagen B: 3,15 Punkte schlägt A mit 2,6"},en:{term:"Scoring method (utility analysis)",erklaerung:"Rates alternatives on qualitative criteria too: define and weight criteria (100%), award points, add up points × weights – the highest utility value wins.",beispiel:"E-van B with 3.15 points beats A with 2.6"},hu:{term:"Pontozásos módszer (hasznosságelemzés)",erklaerung:"Az alternatívákat minőségi szempontok szerint is értékeli: szempontok és súlyok (100%) meghatározása, pontozás, pont × súly összegzése – a legmagasabb hasznossági érték nyer.",beispiel:"A 3,15 pontos B e-furgon legyőzi a 2,6 pontos A-t"}}],finanzmanagement:[{de:{term:"Innen- vs. Außenfinanzierung",erklaerung:"Einteilung nach der Herkunft des Kapitals: Innenfinanzierung aus der eigenen betrieblichen Tätigkeit (Gewinne, Abschreibungen, Rückstellungen), Außenfinanzierung von externen Geldgebern (Einlagen, Kredite).",beispiel:"Einbehaltener Gewinn ↔ Bankkredit"},en:{term:"Internal vs. external financing",erklaerung:"Classification by source of capital: internal financing from the company's own operations (profits, depreciation, provisions), external financing from outside providers (contributions, loans).",beispiel:"Retained profit ↔ bank loan"},hu:{term:"Belső vs. külső finanszírozás",erklaerung:"Felosztás a tőke eredete szerint: belső finanszírozás a saját üzleti tevékenységből (nyereség, értékcsökkenés, céltartalék), külső finanszírozás külső tőkeadóktól (betétek, hitelek).",beispiel:"Visszatartott nyereség ↔ bankhitel"}},{de:{term:"Offene vs. stille Selbstfinanzierung",erklaerung:"Offen: Gewinne werden nicht ausgeschüttet und bleiben als Rücklagen im Unternehmen. Still: stille Reserven durch Bilanzierungsregeln (Aktiva zu niedrig, Passiva zu hoch bewertet).",beispiel:"Grundstück um 200.000 € bilanziert, Marktwert 1,5 Mio. €"},en:{term:"Open vs. silent self-financing",erklaerung:"Open: profits are not distributed and stay in the company as reserves. Silent: hidden reserves arise from accounting rules (assets valued too low, liabilities too high).",beispiel:"Land on the books at €200,000, market value €1.5m"},hu:{term:"Nyílt vs. rejtett önfinanszírozás",erklaerung:"Nyílt: a nyereséget nem fizetik ki, tartalékként a vállalatnál marad. Rejtett: rejtett tartalékok a számviteli szabályok miatt (eszközök alul-, források felülértékelve).",beispiel:"Telek 200 000 €-n a mérlegben, piaci érték 1,5 millió €"}},{de:{term:"Hypothek vs. Lombard",erklaerung:"Zwei Formen des Pfandrechts: Hypothek = Pfandrecht an Grundstücken, im Grundbuch eingetragen. Lombard = Pfandrecht an beweglichen Gütern wie Gold oder Wertpapieren.",beispiel:"Kredit für eine Werkshalle → Hypothek auf das Betriebsgrundstück"},en:{term:"Mortgage vs. lombard pledge",erklaerung:"Two forms of lien: mortgage = lien on land, entered in the land register. Lombard pledge = lien on movable goods such as gold or securities.",beispiel:"Loan for a workshop → mortgage on the business property"},hu:{term:"Jelzálog vs. lombard",erklaerung:"A zálogjog két formája: jelzálog = zálogjog ingatlanon, az ingatlan-nyilvántartásba bejegyezve. Lombard = zálogjog ingóságokon, pl. aranyon vagy értékpapíron.",beispiel:"Hitel üzemcsarnokra → jelzálog az üzemi telken"}},{de:{term:"Kontokorrentkredit vs. Darlehen",erklaerung:"Kontokorrent: kurzfristiger Kreditrahmen am Girokonto, laufend nutzbar, teuer. Darlehen: langfristiger Betrag, nur einmal in Anspruch genommen, günstiger – passend für Anlagevermögen."},en:{term:"Overdraft facility vs. loan",erklaerung:"Overdraft: short-term credit line on the current account, usable on a rolling basis, expensive. Loan: long-term amount, drawn only once, cheaper – suitable for fixed assets."},hu:{term:"Folyószámlahitel vs. kölcsön",erklaerung:"Folyószámlahitel: rövid távú hitelkeret a bankszámlán, folyamatosan igénybe vehető, drága. Kölcsön: hosszú távú összeg, egyszer folyósítják, olcsóbb – befektetett eszközökhöz illik."}},{de:{term:"Skonto-Jahreszinssatz",erklaerung:"Skontosatz · 360 / (Zahlungsziel − Kassafrist). Zeigt, wie teuer der Lieferantenkredit ist, wenn man den Skonto nicht nutzt.",beispiel:"3 · 360 / (30 − 8) = 49,09 % p. a. → Skonto nutzen!"},en:{term:"Annual interest rate of a cash discount",erklaerung:"Discount rate · 360 / (payment term − discount period). Shows how expensive supplier credit is if you do not take the discount.",beispiel:"3 · 360 / (30 − 8) = 49.09% p.a. → take the discount!"},hu:{term:"A skontó éves kamatlába",erklaerung:"Skontó % · 360 / (fizetési határidő − skontóhatáridő). Megmutatja, mennyibe kerül a szállítói hitel, ha nem élünk a skontóval.",beispiel:"3 · 360 / (30 − 8) = évi 49,09% → éljünk a skontóval!"}}],"finanzplan-analyse":[{de:{term:"Eigenkapitalquote",erklaerung:"Eigenkapital · 100 / Gesamtkapital. Zeigt die finanzielle Stabilität: > 30 % sehr gut, > 20 % gut, < 10 % schlecht, negativ = insolvenzgefährdet.",beispiel:"120.000 / 400.000 · 100 = 30 %"},en:{term:"Equity ratio",erklaerung:"Equity · 100 / total capital. Shows financial stability: > 30% very good, > 20% good, < 10% poor, negative = at risk of insolvency.",beispiel:"120,000 / 400,000 · 100 = 30%"},hu:{term:"Saját tőke aránya",erklaerung:"Saját tőke · 100 / összes tőke. A pénzügyi stabilitást mutatja: > 30% nagyon jó, > 20% jó, < 10% gyenge, negatív = fizetésképtelenség fenyegeti.",beispiel:"120 000 / 400 000 · 100 = 30%"}},{de:{term:"Verschuldungskoeffizient",erklaerung:"Fremdkapital / Eigenkapital. Zeigt, wie viel Euro Fremdkapital auf 1 Euro Eigenkapital kommen. Richtwert EK : FK = 1 : 2 sehr gut, 1 : 3 gut."},en:{term:"Debt-to-equity ratio",erklaerung:"Debt / equity. Shows how many euros of debt there are per euro of equity. Benchmark equity : debt = 1 : 2 very good, 1 : 3 good."},hu:{term:"Eladósodottsági mutató",erklaerung:"Idegen tőke / saját tőke. Megmutatja, hány euró idegen tőke jut 1 euró saját tőkére. Irányérték saját : idegen = 1 : 2 nagyon jó, 1 : 3 jó."}},{de:{term:"Fiktive Schuldentilgungsdauer",erklaerung:"(Fremdkapital − Zahlungsmittel) / operativer Cashflow. In wie vielen Jahren könnten die Schulden aus dem Cashflow getilgt werden? < 3 J. sehr gut, > 15 J. insolvenzgefährdet."},en:{term:"Notional debt repayment period",erklaerung:"(Debt − cash) / operating cash flow. In how many years could debts be repaid from cash flow? < 3 years very good, > 15 years at risk of insolvency."},hu:{term:"Fiktív adósságtörlesztési idő",erklaerung:"(Idegen tőke − pénzeszközök) / működési cash flow. Hány év alatt lehetne a tartozásokat a cash flow-ból visszafizetni? < 3 év nagyon jó, > 15 év fizetésképtelenség fenyegeti."}},{de:{term:"Anlagendeckung (Goldene Finanzierungsregel)",erklaerung:"(Eigenkapital + langfristiges Fremdkapital) · 100 / Anlagevermögen. Mindestens 100 %: Langfristiges Vermögen soll mit langfristigem Kapital finanziert werden."},en:{term:"Fixed asset coverage (golden rule of financing)",erklaerung:"(Equity + long-term debt) · 100 / fixed assets. At least 100%: long-term assets should be financed with long-term capital."},hu:{term:"Befektetett eszközök fedezettsége (aranyszabály)",erklaerung:"(Saját tőke + hosszú lejáratú idegen tőke) · 100 / befektetett eszközök. Legalább 100%: a hosszú távú vagyont hosszú távú tőkéből kell finanszírozni."}},{de:{term:"Liquidität 1., 2. und 3. Grades",erklaerung:"Zahlungsmittel (1.), + kurzfristige Forderungen (2.), + Vorräte (3.) jeweils · 100 / kurzfristige Verbindlichkeiten. Zielwerte: 20–50 %, 100–120 %, 150–200 %."},en:{term:"1st, 2nd and 3rd degree liquidity",erklaerung:"Cash (1st), + short-term receivables (2nd), + inventory (3rd), each · 100 / short-term liabilities. Targets: 20–50%, 100–120%, 150–200%."},hu:{term:"Első-, másod- és harmadfokú likviditás",erklaerung:"Pénzeszközök (1.), + rövid lejáratú követelések (2.), + készletek (3.), mindegyik · 100 / rövid lejáratú kötelezettségek. Célértékek: 20–50%, 100–120%, 150–200%."}},{de:{term:"Working Capital",erklaerung:"Umlaufvermögen − kurzfristige Verbindlichkeiten. Soll positiv sein: Dann sind die kurzfristigen Schulden durch kurzfristig verfügbares Vermögen gedeckt."},en:{term:"Working capital",erklaerung:"Current assets − short-term liabilities. Should be positive: then short-term debts are covered by assets available in the short term."},hu:{term:"Nettó forgótőke (working capital)",erklaerung:"Forgóeszközök − rövid lejáratú kötelezettségek. Pozitívnak kell lennie: ekkor a rövid lejáratú tartozásokat a rövid távon mozgósítható vagyon fedezi."}},{de:{term:"Operativer Cashflow (indirekt)",erklaerung:"Jahresüberschuss + nicht auszahlungswirksame Aufwendungen (z. B. Abschreibungen) − nicht einzahlungswirksame Erträge (z. B. Auflösung von Rückstellungen).",beispiel:"40.000 + 25.000 − 5.000 = 60.000 €"},en:{term:"Operating cash flow (indirect)",erklaerung:"Net profit + non-cash expenses (e.g. depreciation) − non-cash income (e.g. release of provisions).",beispiel:"40,000 + 25,000 − 5,000 = €60,000"},hu:{term:"Működési cash flow (közvetett)",erklaerung:"Nyereség + nem pénzkiadással járó ráfordítások (pl. értékcsökkenés) − nem pénzbevétellel járó bevételek (pl. céltartalék feloldása).",beispiel:"40 000 + 25 000 − 5000 = 60 000 €"}},{de:{term:"Eigen- vs. Gesamtkapitalrentabilität",erklaerung:"EK-Rentabilität = Ergebnis vor Steuern · 100 / Eigenkapital. GK-Rentabilität = (Ergebnis vor Steuern + FK-Zinsen) · 100 / Gesamtkapital; > 10 % gut, > 15 % sehr gut."},en:{term:"Return on equity vs. return on total capital",erklaerung:"ROE = profit before tax · 100 / equity. Return on total capital = (profit before tax + interest on debt) · 100 / total capital; > 10% good, > 15% very good."},hu:{term:"Saját tőke vs. összes tőke arányos jövedelmezőség",erklaerung:"ROE = adózás előtti eredmény · 100 / saját tőke. Összes tőke arányos = (adózás előtti eredmény + kamatok) · 100 / összes tőke; > 10% jó, > 15% nagyon jó."}}],"businessplan-3jg":[{de:{term:"Teilplanungen des Finanzplans",erklaerung:"Der Finanzplan im Businessplan (meist 3–5 Jahre) besteht aus: Umsatzplanung, Sach- und Personalaufwand, Investition und Finanzierung, Erfolg und Liquidität."},en:{term:"Sub-plans of the financial plan",erklaerung:"The financial plan in a business plan (usually 3–5 years) consists of: revenue planning, operating and personnel expenses, investment and financing, profit and liquidity."},hu:{term:"A pénzügyi terv résztervei",erklaerung:"Az üzleti terv pénzügyi terve (általában 3–5 évre) a következőkből áll: árbevétel-tervezés, dologi és személyi ráfordítások, beruházás és finanszírozás, eredmény és likviditás."}},{de:{term:"Planumsatz",erklaerung:"Nettoverkaufspreis · geplante Absatzmenge. Grundlage sind Marktforschung und Zielgruppe – Geldgeber erwarten realistische Annahmen.",beispiel:"Café: 110 Kund:innen · 4,50 € · 300 Tage = 148.500 €"},en:{term:"Planned revenue",erklaerung:"Net selling price · planned sales volume. Based on market research and the target group – investors expect realistic assumptions.",beispiel:"Café: 110 customers · €4.50 · 300 days = €148,500"},hu:{term:"Tervezett árbevétel",erklaerung:"Nettó eladási ár · tervezett értékesítési mennyiség. Alapja a piackutatás és a célcsoport – a tőkeadók reális feltételezéseket várnak.",beispiel:"Kávézó: 110 vendég · 4,50 € · 300 nap = 148 500 €"}},{de:{term:"Investitions- vs. Finanzierungsplanung",erklaerung:"Investitionsplanung: alle aktivierungsfähigen Anfangsinvestitionen mit Abschreibung (Anschaffungswert / Nutzungsdauer). Finanzierungsplanung: passende Quellen wie Eigenmittel, Förderungen, Darlehen, Kontokorrent."},en:{term:"Investment vs. financing planning",erklaerung:"Investment planning: all capitalisable start-up investments with annual depreciation (cost / useful life). Financing planning: suitable sources – own funds, subsidies, loans, overdraft."},hu:{term:"Beruházás- vs. finanszírozástervezés",erklaerung:"Beruházástervezés: minden aktiválható induló beruházás éves értékcsökkenéssel (bekerülési érték / élettartam). Finanszírozástervezés: megfelelő források – saját forrás, támogatás, kölcsön, folyószámlahitel."}},{de:{term:"Erfolgs- vs. Liquiditätsplanung",erklaerung:"Erfolgsplanung (Plan-GuV): Erträge − Aufwände = Gewinn. Liquiditätsplanung: Einzahlungen − Auszahlungen = Cashflow. Gewinn ≠ Geld am Konto!",beispiel:"Kredittilgung: Auszahlung, aber kein Aufwand"},en:{term:"Profit vs. liquidity planning",erklaerung:"Profit planning (planned P&L): income − expenses = profit. Liquidity planning: receipts − payments = cash flow. Profit ≠ money in the account!",beispiel:"Loan repayment: a payment but not an expense"},hu:{term:"Eredmény- vs. likviditástervezés",erklaerung:"Eredménytervezés (tervezett eredménykimutatás): bevételek − ráfordítások = nyereség. Likviditástervezés: befizetések − kifizetések = cash flow. Nyereség ≠ pénz a számlán!",beispiel:"Hiteltörlesztés: kifizetés, de nem ráfordítás"}},{de:{term:"DBU-Quote",erklaerung:"Deckungsbeitrag gesamt · 100 / Umsatz (Deckungsbeitrag = Umsatz − variable Kosten). Zeigt, wie viel Prozent jedes Umsatz-Euros zur Deckung der Fixkosten bleibt.",beispiel:"96.500 / 148.500 · 100 = 64,98 %"},en:{term:"Contribution margin ratio",erklaerung:"Total contribution margin · 100 / revenue (contribution margin = revenue − variable costs). Shows what share of each euro of revenue is left to cover fixed costs.",beispiel:"96,500 / 148,500 · 100 = 64.98%"},hu:{term:"Fedezeti hányad",erklaerung:"Összes fedezeti hozzájárulás · 100 / árbevétel (fedezeti hozzájárulás = árbevétel − változó költségek). Megmutatja, minden árbevétel-euró hány százaléka marad a fix költségek fedezésére.",beispiel:"96 500 / 148 500 · 100 = 64,98%"}},{de:{term:"Break-even-Umsatz",erklaerung:"Fixkosten / DBU-Quote. Mindestumsatz, ab dem weder Gewinn noch Verlust entsteht; steigen die Fixkosten, steigt er mit.",beispiel:"86.900 / 0,6498 = 133.733,46 €"},en:{term:"Break-even revenue",erklaerung:"Fixed costs / contribution margin ratio. The minimum revenue at which there is neither profit nor loss; it rises when fixed costs rise.",beispiel:"86,900 / 0.6498 = €133,733.46"},hu:{term:"Fedezeti árbevétel",erklaerung:"Fix költségek / fedezeti hányad. Az a minimális árbevétel, amelynél sem nyereség, sem veszteség nem keletkezik; a fix költségekkel együtt nő.",beispiel:"86 900 / 0,6498 = 133 733,46 €"}},{de:{term:"Fiktiver Unternehmerlohn",erklaerung:"Bei Einzelunternehmen zählen Privatentnahmen + Einkommensteuer als fiktiver Unternehmerlohn zu den Fixkosten der Break-even-Berechnung, da sie kein Gehalt bezieht.",beispiel:"Fixkosten 54.000 € + Unternehmerlohn 30.000 € = 84.000 €"},en:{term:"Notional entrepreneur's salary",erklaerung:"For sole traders, private withdrawals and income tax count as a notional entrepreneur's salary within fixed costs in the break-even calculation – the owner receives no salary.",beispiel:"Fixed costs €54,000 + entrepreneur's salary €30,000 = €84,000"},hu:{term:"Kalkulatív vállalkozói bér",erklaerung:"Egyéni vállalkozásnál a magáncélú kivétek és a jövedelemadó kalkulatív vállalkozói bérként a fix költségekhez számítanak a fedezetipont-számításban – a tulajdonos nem kap fizetést.",beispiel:"Fix költség 54 000 € + vállalkozói bér 30 000 € = 84 000 €"}}]},i=e(t,n);export{i as default};
